/* CDSTUHUE • 05/11/2026: Canonical reviewed QA updates (WEB_PUBLISH).
   Synced with source Sheet: answers are rendered as primary content, not a notice. */
(()=>{'use strict';
const corrections={"QA006":{"question":"Đảng phí miễn 100% hoặc được giảm mức đóng xử lý thế nào theo quy trình mới?","answer":"Hệ thống tự tính và tạo nghĩa vụ đảng phí theo kỳ. Miễn/giảm cần được cấu hình đúng; miễn 100% không phát sinh khoản tiền phải thanh toán.\n\n1. Mở Thu nộp Đảng phí → Xem chi tiết nghĩa vụ → chọn kỳ và kiểm tra mức miễn/giảm.\n2. Nếu số tiền hoặc tỷ lệ miễn/giảm sai, gửi Yêu cầu điều chỉnh kèm minh chứng để cán bộ chi bộ xem xét.\n3. Không phải lập tờ khai hằng tháng rồi chờ phê duyệt."},"QA007":{"question":"Đảng phí hằng tháng có cần Bí thư phê duyệt không? Các trạng thái thanh toán diễn ra thế nào?","answer":"Đảng phí bình thường KHÔNG phải chờ Bí thư/Ủy viên tài chính phê duyệt. Hệ thống tự tính nghĩa vụ, đảng viên kiểm tra và nộp trực tiếp.\n\n1. Dữ liệu BHXH được tiếp nhận ngày 05; kỳ thu mở lúc 00:00 ngày 06 hằng tháng.\n2. Số tiền đúng: Thu nộp Đảng phí → Xem chi tiết nghĩa vụ → chọn kỳ → Đóng/Nộp đảng phí → thanh toán. Ngân hàng xác nhận thì hệ thống chuyển Đã nộp, có biên lai điện tử.\n3. Số tiền chưa đúng: đảng viên gửi đề nghị xem xét/điều chỉnh, kèm minh chứng; cán bộ phụ trách chi bộ xác nhận mức đóng. Chỉ trường hợp này mới có bước xét duyệt.\n4. Miễn 100% đúng cấu hình thì hệ thống có thể hoàn thành khoản 0 đồng không cần thanh toán."},"QA017":{"question":"Số tiền đảng phí do BHXH tính sai thì đề nghị điều chỉnh ở đâu?","answer":"Mức đóng tính từ BHXH chưa đúng thì gửi Yêu cầu điều chỉnh, không chờ phê duyệt tờ khai tháng.\n\n1. Vào Thu nộp Đảng phí → Xem chi tiết nghĩa vụ → chọn kỳ.\n2. Chọn Yêu cầu điều chỉnh/Gửi thông tin mức đảng phí, nêu mức đề nghị, lý do, đính kèm minh chứng.\n3. Cán bộ được phân quyền xem xét; sau khi xác nhận mức, đảng viên thanh toán."},"QA026":{"question":"Đảng phí hằng tháng có cần Bí thư/Ủy viên tài chính phê duyệt không? Khi nào phải xét duyệt?","answer":"Không cần Bí thư hoặc Ủy viên tài chính phê duyệt đảng phí định kỳ khi hệ thống đã tính đúng. Chỉ yêu cầu điều chỉnh mức đóng mới cần cán bộ có quyền xét duyệt.\n\n1. Nếu số tiền đúng, đảng viên thanh toán thẳng qua ngân hàng.\n2. Nếu số tiền sai, gửi yêu cầu điều chỉnh kèm minh chứng.\n3. Cán bộ phụ trách chi bộ được phân quyền vào Quản lý hồ sơ Đảng phí → Hồ sơ cần điều chỉnh → Xử lý yêu cầu để xét mức đóng."},"QA030":{"question":"Hằng tháng hệ thống tự tạo nghĩa vụ đảng phí như thế nào, có cần phê duyệt tự động không?","answer":"Cơ chế mới tự tính và tự tạo nghĩa vụ đảng phí hằng tháng, không có bước duyệt tờ khai thường kỳ.\n\n1. Dữ liệu BHXH nhận ngày 05; mở thu từ 00:00 ngày 06.\n2. Nếu số tiền đúng, đảng viên nộp trực tiếp. Nếu sai, gửi yêu cầu điều chỉnh để được xem xét.\n3. Không cần bật chức năng tự phê duyệt tờ khai như quy trình trước."},"QA033":{"question":"Đã đóng thiếu đảng phí của tháng trước thì nộp bù/truy thu như thế nào?","answer":"Khoản đảng phí nộp thiếu các tháng trước được truy thu vào kỳ nộp hiện tại; không mở lại các tháng đã khóa sổ.\n\n1. Nếu BHXH có dữ liệu chênh lệch, hệ thống tự tính truy thu.\n2. Nếu chưa có dữ liệu, đảng viên cung cấp trong yêu cầu điều chỉnh để cán bộ được phân quyền xác nhận.\n3. Nộp khoản kỳ này cùng tiền truy thu; hệ thống phân bổ vào tháng nộp bù."},"QA042":{"question":"Không thấy hồ sơ đảng phí để Bí thư duyệt có phải lỗi không?","answer":"Với kỳ đảng phí bình thường, Bí thư không cần nhận hồ sơ để duyệt. Không thấy hồ sơ chờ duyệt chưa phải lỗi.\n\n1. Đảng viên kiểm tra Xem chi tiết nghĩa vụ theo đúng kỳ thu.\n2. Số tiền đúng thì thanh toán trực tiếp, không chờ phê duyệt.\n3. Chỉ khi đã gửi Yêu cầu điều chỉnh mà cán bộ không thấy hồ sơ mới cần kiểm tra phân quyền, kỳ thu và đồng bộ tổ chức đảng."},"QA063":{"question":"Chưa xác nhận tỷ lệ phân bổ có chặn việc đảng viên nộp đảng phí không?","answer":"Xác nhận tỷ lệ phân bổ là công việc riêng để đơn vị nhận tiền, không phải điều kiện duyệt tờ khai đảng phí định kỳ.\n\n1. Đảng viên thanh toán nghĩa vụ nếu hệ thống tính đúng, không cần cán bộ duyệt tờ khai.\n2. Đơn vị muốn nhận phần phân bổ phải xác thực tài khoản ngân hàng của tổ chức và xác nhận tỷ lệ phân bổ.\n3. Thiếu điều kiện nhận phân bổ có thể khiến tiền chưa chuyển về đơn vị; không đồng nghĩa khoản đảng phí chưa được nộp."},"QA104":{"question":"Hệ thống tính sai mức đảng phí thì gửi yêu cầu điều chỉnh như thế nào?","answer":"Sai số tiền đảng phí: dùng Yêu cầu điều chỉnh và đính kèm minh chứng; không phải từ chối tờ khai định kỳ để khai lại.\n\n1. Mở Xem chi tiết nghĩa vụ → chọn kỳ → Yêu cầu điều chỉnh.\n2. Ghi mức đề nghị và lý do, gửi minh chứng.\n3. Cán bộ được phân quyền xử lý yêu cầu; đảng viên nộp sau khi mức được xác nhận."},"QA110":{"question":"Đảng viên kiểm tra và nộp đảng phí hằng tháng theo quy trình mới thế nào?","answer":"Đảng viên không phải tự kê khai hồ sơ và chờ Bí thư duyệt mỗi tháng. Hệ thống tự tạo nghĩa vụ, đảng viên đối chiếu rồi nộp.\n\n1. Vào Thu nộp Đảng phí → Xem chi tiết nghĩa vụ → chọn kỳ.\n2. Kiểm tra căn cứ tính, truy thu/giảm trừ, miễn/giảm và số phải đóng.\n3. Nếu đúng, bấm Đóng đảng phí → chọn phương thức → thanh toán qua ngân hàng.\n4. Sau khi ngân hàng xác nhận, kiểm tra trạng thái Đã nộp và biên lai. Nếu sai mức, gửi Yêu cầu điều chỉnh trước khi thanh toán."},"QA111":{"question":"Nộp hộ đảng phí cho người khác theo quy trình mới như thế nào?","answer":"Nộp hộ là thanh toán nghĩa vụ đã được hệ thống tính cho người khác, không phải khai hộ hồ sơ định kỳ chờ duyệt.\n\n1. Trong Thu nộp Đảng phí, mở mục nộp hộ và Xem chi tiết nghĩa vụ.\n2. Tra cứu đúng người bằng CCCD, họ tên, ngày sinh theo các trường yêu cầu.\n3. Đối chiếu kỳ, số tiền và thanh toán qua ngân hàng; nếu mức tính sai thì gửi điều chỉnh trước khi nộp."},"QA120":{"question":"Yêu cầu điều chỉnh đảng phí chuyển sai cấp xử lý thì kiểm tra thế nào?","answer":"Đảng phí thường kỳ không phải gửi tờ khai lên Đảng bộ để phê duyệt. Chỉ cần kiểm tra tuyến xử lý khi yêu cầu điều chỉnh bị chuyển sai cấp.\n\n1. Nghĩa vụ đúng: đảng viên nộp trực tiếp.\n2. Nếu yêu cầu điều chỉnh đi sai cấp, kiểm tra kỳ, mã hồ sơ, cây tổ chức và tài khoản có quyền xử lý.\n3. Nếu dữ liệu tổ chức chưa đồng bộ, chuyển đầu mối quản trị để xử lý định tuyến, không duyệt nhầm cấp."},"QA122":{"question":"Hệ thống báo không nợ đảng phí dù chưa nộp: kiểm tra thế nào?","answer":"Hệ thống báo không nợ đảng phí: kiểm tra kỳ thu và nghĩa vụ tự sinh, không yêu cầu tạo tờ khai mới rồi chờ Bí thư duyệt.\n\n1. Mở Thu nộp Đảng phí → Xem chi tiết nghĩa vụ → chọn đúng kỳ (mở thu từ 00:00 ngày 06).\n2. Kiểm tra số phải nộp, miễn/giảm và dữ liệu BHXH.\n3. Nếu mức tính sai, gửi Yêu cầu điều chỉnh; nếu nghĩa vụ dương nhưng báo không nợ thì lưu thông tin kỳ, trạng thái và nhờ hỗ trợ tra soát.\n4. Không tạo giao dịch thanh toán thử để tránh trùng."},"QA003":{"question":null,"answer":"Đảng viên thanh toán đảng phí qua cổng thanh toán; số tiền trước hết vào tài khoản trung gian để đối soát, không chuyển ngay toàn bộ vào tài khoản chi bộ.\n\nHệ thống gom và phân bổ phần được hưởng của chi bộ trong chu kỳ T đến T+2 theo điều kiện đã xác thực; phần cấp trên được phân bổ tiếp theo tỷ lệ, với mốc T+10 mô tả trong quy trình đào tạo.\n\nĐể nhận tiền, mỗi tổ chức đảng phải khai báo/xác thực tài khoản ngân hàng đứng tên tổ chức và xác nhận tỷ lệ phân bổ. Nếu thiếu điều kiện, khoản tiền có thể đã được đảng viên nộp thành công nhưng chưa chuyển về đơn vị."},"QA005":{"question":null,"answer":"Nộp thừa: đảng viên tạo Yêu cầu hoàn tiền, ghi mã giao dịch, số tiền đề nghị hoàn, lý do và tài khoản nhận. Bí thư/cán bộ phụ trách đảng phí chi bộ đối chiếu số phải nộp, số đã nộp, duyệt hoặc từ chối và nêu lý do. Đơn vị trung gian thanh toán đối soát, hoàn tiền; hệ thống cập nhật kết quả.\n\nChỉ hoàn được phần tiền nộp thừa khi khoản tiền còn tại tài khoản trung gian, CHƯA phân bổ. Không hoàn cả hồ sơ nếu chỉ thừa một phần.\n\nNếu tiền đã phân bổ hoặc chuyển nhầm ngoài cổng TTHC, chuyển đầu mối tài chính/đơn vị tiếp nhận để đối soát; không tự ý tạo thanh toán trùng."},"QA008":{"question":"Đảng viên chuyển sinh hoạt tạm thời được quản lý và thu nộp đảng phí ra sao?","answer":"Chuyển sinh hoạt tạm thời có luồng chiều đi và chiều về trên giấy giới thiệu điện tử 8 ô. Sau mỗi chiều, hệ thống cập nhật tình trạng sinh hoạt để phục vụ quản lý đảng viên, đảng số và thu nộp đảng phí đúng đơn vị, đúng giai đoạn.\n\nCần kiểm tra chi bộ đang tiếp nhận sinh hoạt tạm thời và hướng dẫn thu đảng phí của kỳ cụ thể. Các trao đổi trước đây có nêu thu tiền mặt tại chi bộ tạm thời, nhưng không nên coi đó là quy tắc áp dụng cho mọi tài khoản, mọi kỳ sau cập nhật. Nếu nghĩa vụ trên TTHC vẫn gắn sai đơn vị, gửi mã hồ sơ chuyển sinh hoạt và kỳ thu cho đầu mối quản trị đối chiếu; tránh nộp trùng."},"QA012":{"question":"Chi bộ phải phê duyệt điện tử hay ký số khi xử lý giấy giới thiệu chuyển sinh hoạt?","answer":"Không áp dụng một câu trả lời chung cho mọi thủ tục:\n\n- Chuyển sinh hoạt chính thức: chi bộ nơi đi xác nhận ô 1 và chi bộ nơi đến xác nhận ô 6 bằng PHÊ DUYỆT ĐIỆN TỬ, không phải ký số ở hai ô này. Các cấp đảng ủy có trách nhiệm ký số tại bước của mình.\n- Chuyển sinh hoạt tạm thời: theo quy trình 8 ô, chi bộ có thẩm quyền thực hiện ô 1, 4, 5, 8 bằng ký số theo phân quyền; các đảng ủy xử lý ô 2, 3, 6, 7.\n\nCần xác định đúng tên thủ tục, cơ cấu tổ chức và bước hiện tại trước khi đề nghị cấp token hoặc kết luận thiếu chữ ký."},"QA014":{"question":null,"answer":"Việc xác nhận tỷ lệ phân bổ không có nghĩa tiền về ngay. Sau khi đảng viên thanh toán, tiền vào tài khoản trung gian để đối soát; phần chi bộ được hệ thống xử lý phân bổ trong khoảng T đến T+2, phần cấp trên tiếp tục theo chu kỳ T+10 như tài liệu đào tạo mô tả.\n\nĐiều kiện nhận tiền: tài khoản ngân hàng đứng tên tổ chức đảng đã khai báo/xác thực và tỷ lệ phân bổ được xác nhận. Thiếu một trong hai điều kiện thì đơn vị chưa được chuyển tiền về.\n\nNếu quá chu kỳ xử lý mà tài khoản vẫn chưa nhận, đối chiếu kỳ thu, giao dịch, trạng thái phân bổ, tài khoản và tỷ lệ; gửi đầu mối tài chính/đơn vị trung gian tra soát. Các mốc T+2/T+10 là mốc quy trình, không thay cho trạng thái giao dịch thực tế."},"QA018":{"question":"Không hiện tổ chức đảng hoặc danh sách để nộp đảng phí: xử lý thế nào?","answer":"Đảng phí bình thường không yêu cầu đảng viên lập tờ khai hay Bí thư khai hộ trước khi thanh toán. Hệ thống tự tính nghĩa vụ theo kỳ từ dữ liệu liên thông.\n\n1. Kiểm tra thông tin đảng viên, chi bộ và tình trạng sinh hoạt trên CSDL 4.0; đồng bộ lại nếu có quyền và dữ liệu nguồn đã đúng.\n2. Đảng viên mở Thu nộp Đảng phí → Xem chi tiết nghĩa vụ → chọn kỳ. Nếu vẫn không có nghĩa vụ, kiểm tra kỳ đã mở thu (từ ngày 06), đối tượng miễn/giảm và thông tin BHXH.\n3. Nếu thiếu người hoặc sai chi bộ dù dữ liệu nguồn đúng, gửi mã tổ chức, mã hồ sơ (nếu có) và ảnh lỗi cho đầu mối kỹ thuật. Không tạo tờ khai giả hoặc đổi đơn vị chỉ để nộp."},"QA022":{"question":"Chữ ký số và phê duyệt điện tử trong chuyển sinh hoạt chính thức/tạm thời phân biệt thế nào?","answer":"Việc có phải ký số phụ thuộc THỦ TỤC và bước xử lý, không chỉ phụ thuộc tên chi bộ hay loại tổ chức.\n\n- Chuyển chính thức (6 ô): chi bộ nơi đi phê duyệt điện tử ô 1; chi bộ nơi đến phê duyệt điện tử ô 6. Đảng ủy nơi đi/nơi đến ký số các ô theo cơ cấu và luồng hồ sơ; ô 2 hoặc ô 5 có thể bỏ qua khi không có cấp tương ứng.\n- Chuyển tạm thời (8 ô, hai chiều): chi bộ nơi đi/nơi đến và đảng ủy được phân quyền ký số các ô 1–8 theo từng chiều.\n\nKhi tài khoản không có nút ký, trước tiên kiểm tra đúng hồ sơ, vai trò, loại tổ chức và bước phải xử lý; không tự gắn thêm quyền."},"QA027":{"question":"Khi nộp hộ đảng phí cho đảng viên không có số điện thoại thì cần thông tin gì?","answer":"Theo quy trình mới, người nộp hộ mở Thu nộp Đảng phí → mục Nộp hộ/Xem chi tiết nghĩa vụ, tra cứu đảng viên bằng các trường định danh hệ thống yêu cầu (CCCD hoặc số thẻ, họ tên và ngày sinh tùy màn hình), đối chiếu đúng người, kỳ và số tiền rồi thanh toán.\n\nKhông cần tự lập tờ khai hộ định kỳ. Nếu màn hình bắt buộc số điện thoại nhưng đảng viên không có, không tự nhập số người thân khi chưa được cơ quan phụ trách xác nhận; chuyển đầu mối hỗ trợ xử lý thông tin liên hệ."},"QA028":{"question":"Danh sách người cần nộp hộ không hiển thị đủ hoặc khó tìm thì xử lý thế nào?","answer":"Quy trình hiện hành có chức năng Nộp hộ đảng phí: tra cứu theo thông tin định danh, không phụ thuộc việc mở danh sách kê khai hộ rồi chờ duyệt.\n\n1. Vào Thu nộp Đảng phí → Nộp hộ/Xem chi tiết nghĩa vụ.\n2. Dùng các tiêu chí tra cứu được hệ thống hỗ trợ; đối chiếu đúng đảng viên, kỳ và số tiền.\n3. Nếu vẫn không tìm được người hoặc danh sách thiếu trên 100 người, kiểm tra dữ liệu đảng viên và chi bộ đã đồng bộ; gửi tài khoản có quyền, đơn vị, thời điểm, ảnh lỗi cho kỹ thuật. Không tự đổi số CCCD hoặc tạo người trùng."},"QA034":{"question":"Chưa thanh toán nhưng số tiền đảng phí cần đổi: làm thế nào?","answer":"Với quy trình mới, không còn bước duyệt tờ khai hằng tháng để thực hiện thao tác hủy duyệt → từ chối → kê khai lại.\n\nĐảng viên vào Thu nộp Đảng phí → Xem chi tiết nghĩa vụ → chọn kỳ, nếu mức đóng chưa đúng thì gửi Yêu cầu điều chỉnh (hoặc Gửi thông tin mức đảng phí), ghi lý do và đính kèm minh chứng.\n\nCán bộ phụ trách được phân quyền xem xét điều chỉnh và ghi rõ mức đã xác nhận. Sau khi nghĩa vụ được cập nhật, đảng viên thanh toán. Trường hợp đã phát sinh giao dịch, không tự ý tạo giao dịch mới hoặc hủy đối soát."},"QA036":{"question":"Đảng viên dự bị không thấy nghĩa vụ đảng phí: kiểm tra thế nào?","answer":"Không còn thủ tục đảng viên dự bị phải tự tạo tờ khai thu đảng phí để chờ duyệt hằng tháng.\n\nKiểm tra dữ liệu đảng viên dự bị trên CSDL 4.0 (trạng thái, đơn vị, thông tin nhận diện), đồng bộ sang TTHC nếu có quyền. Vào Thu nộp Đảng phí → Xem chi tiết nghĩa vụ theo kỳ, kiểm tra đối tượng và số tiền tự tính.\n\nNếu người/đơn vị đã đúng nhưng không có nghĩa vụ hoặc không tra cứu được, gửi trường hợp cụ thể cho kỹ thuật; không tự sửa ngày chính thức, trạng thái hay số tiền chỉ để vượt lỗi."},"QA047":{"question":"Khi nào chi bộ cần ký số, khi nào chỉ phê duyệt điện tử trong TTHC?","answer":"Phải xác định loại thủ tục và bước cụ thể, thay vì coi mọi thao tác duyệt hồ sơ đều cần chữ ký số cá nhân.\n\nChuyển sinh hoạt CHÍNH THỨC: chi bộ xác nhận ô 1/ô 6 bằng phê duyệt điện tử, không ký số ở hai ô này; các cấp đảng ủy có bước ký số riêng.\n\nChuyển sinh hoạt TẠM THỜI: giấy giới thiệu 8 ô có ký số theo thẩm quyền từng cấp, kể cả bước tại chi bộ.\n\nChỉ dùng chữ ký số đã được cơ quan cấp/chấp nhận hợp lệ theo phân quyền hiện hành; không suy từ một ca hỗ trợ trước đây rằng mọi chữ ký VNPT/Viettel đều được chấp nhận cho mọi vai trò."},"QA052":{"question":"Mỗi tháng có phải tự kê khai và xin duyệt đảng phí lại không?","answer":"Không. Từ quy trình thu, nộp đảng phí điện tử cập nhật ngày 31/10/2026, hệ thống tự lấy dữ liệu BHXH vào ngày 05 và mở kỳ thu từ 00:00 ngày 06 hằng tháng; nghĩa vụ được tính và hồ sơ được tự sinh theo kỳ.\n\nĐảng viên chỉ chọn kỳ trong Thu nộp Đảng phí → Xem chi tiết nghĩa vụ, đối chiếu số phải đóng và thanh toán nếu đúng. Nếu dữ liệu chưa đúng hoặc thay đổi, gửi yêu cầu điều chỉnh kèm minh chứng để cán bộ phụ trách xem xét.\n\nKhông phải lập tờ khai/tháng rồi chờ Bí thư phê duyệt."},"QA053":{"question":"Một tháng đã nộp thiếu có tạo thêm hồ sơ lần hai được không?","answer":"Không tự tạo thêm hồ sơ nộp đảng phí tháng đã hoàn thành hoặc thanh toán thử lần hai nếu không có chức năng được xác nhận.\n\nTheo quy trình truy thu cập nhật, khoản thiếu các tháng trước được cộng vào nghĩa vụ kỳ hiện tại: hệ thống tự tính khi có dữ liệu BHXH; trường hợp dữ liệu còn thiếu, đảng viên gửi điều chỉnh và cán bộ được phân quyền xác nhận mức.\n\nNếu phát hiện thiếu ngay trong cùng tháng sau khi thanh toán, cần tra soát trạng thái và hỏi đầu mối nghiệp vụ về xử lý khoản chênh lệch; không tự kết luận phải nộp lại toàn bộ."},"QA056":{"question":null,"answer":"Phân quyền theo đúng chức năng và thủ tục:\n\n- Quản trị: quản lý tài khoản, quyền, đơn vị và tài khoản ngân hàng tổ chức.\n- Đảng viên: tra cứu và thanh toán nghĩa vụ đảng phí tự sinh; không cần quyền duyệt tờ khai hằng tháng.\n- Bí thư/cán bộ phụ trách đảng phí: xử lý yêu cầu ĐIỀU CHỈNH mức đóng, hoàn tiền khi được giao quyền, không phải duyệt mọi kỳ thu.\n- Xử lý chuyển sinh hoạt chính thức/tạm thời: chi bộ/đảng ủy xác nhận hoặc ký số đúng bước, phân biệt phê duyệt điện tử và chữ ký số theo thủ tục.\n- Văn thư/ký tổ chức: đóng dấu, ký số theo luồng nhận xét nơi cư trú và phân quyền đã thiết lập.\n\nKhông tự gán quyền ngoài thẩm quyền chỉ vì tài khoản chưa thấy nút."},"QA057":{"question":"BHXH tính mức đảng phí sai đối tượng thì điều chỉnh thế nào?","answer":"Đảng viên mở Thu nộp Đảng phí → Xem chi tiết nghĩa vụ → chọn kỳ và kiểm tra căn cứ BHXH, nhóm đối tượng, mức đóng. Không tự chuyển sang một nhóm khác hoặc nhập số tiền tùy ý chỉ để hệ thống cho nộp.\n\nNếu số hiển thị chưa đúng, chọn Yêu cầu điều chỉnh/Gửi thông tin mức đảng phí, khai mức đề nghị, lý do và đính kèm minh chứng. Bí thư/cán bộ được phân quyền kiểm tra căn cứ, xác nhận hoặc điều chỉnh trước khi đảng viên thanh toán."},"QA058":{"question":"Chuyển sinh hoạt tạm thời có cắt khỏi chi bộ gốc và ảnh hưởng đảng phí không?","answer":"Chuyển sinh hoạt TẠM THỜI khác chuyển sinh hoạt chính thức: đảng viên có thời gian sinh hoạt tại chi bộ tạm thời rồi trở về chi bộ chính thức; giấy giới thiệu điện tử gồm 8 ô, 4 ô chiều đi và 4 ô chiều về.\n\nSau mỗi chiều, hệ thống cập nhật tình trạng sinh hoạt đảng để phục vụ quản lý đảng số và thu nộp đảng phí. Không tự xóa đảng viên khỏi hồ sơ quản lý chính thức chỉ vì chuyển tạm thời.\n\nĐối với kỳ đảng phí, kiểm tra đơn vị sinh hoạt thực tế và nghĩa vụ trên hệ thống; không khẳng định mặc định tất cả trường hợp chỉ thu tiền mặt khi quy trình điện tử đã thay đổi."},"QA059":{"question":"Đảng viên tạm thời đã chuyển nhưng TTHC vẫn hiển thị chi bộ gốc: có sai không?","answer":"Không chỉ dựa vào việc TTHC còn hiển thị chi bộ chính thức để kết luận đồng bộ sai, vì chuyển sinh hoạt tạm thời có chiều đi và chiều về, và hồ sơ quản lý gốc vẫn được lưu.\n\nKiểm tra giấy giới thiệu tạm thời điện tử đã ký đủ ô 1–4 (chiều đi) hay ô 5–8 (chiều về), trạng thái tiếp nhận của chi bộ tạm thời, thông tin CSDL 4.0 và kỳ đảng phí đang xử lý.\n\nNếu kết quả đã hoàn tất nhưng tình trạng sinh hoạt/đơn vị thu phí không khớp, gửi mã hồ sơ và kỳ thu cho đầu mối đồng bộ kiểm tra. Không tự sửa hoặc nộp trùng."},"QA060":{"question":"Đơn vị đang chuyển giai đoạn triển khai thu đảng phí thì xử lý nghĩa vụ đã phát sinh ra sao?","answer":"Đối với quy trình điện tử hiện hành, khi kỳ thu mở, hệ thống tự tính nghĩa vụ và đảng viên thanh toán nếu số tiền đúng; không có bước Bí thư phê duyệt hồ sơ thu định kỳ.\n\nNếu địa phương đang trong giai đoạn chuyển tiếp, đơn vị chưa được phép thu trên cổng theo chỉ đạo riêng hoặc một khoản đã phát sinh trước khi chính thức triển khai, phải đối chiếu chỉ đạo áp dụng cho kỳ đó và trạng thái giao dịch; không phê duyệt hay hủy hồ sơ theo hướng dẫn cũ chỉ để thử.\n\nGửi mã hồ sơ, kỳ thu và tổ chức đảng cho đầu mối tài chính/triển khai để xác định cách tiếp nhận hoặc xử lý."},"QA061":{"question":"Hồ sơ đảng phí cũ còn hiển thị nhưng thanh toán báo không tồn tại thì xử lý thế nào?","answer":"Trước hết kiểm tra kỳ thu hiện tại trong Thu nộp Đảng phí → Xem chi tiết nghĩa vụ; hệ thống tự sinh nghĩa vụ mới và kỳ thu mở từ 00:00 ngày 06 hằng tháng.\n\nHồ sơ cũ trước cập nhật có thể không còn ở luồng thanh toán hiện hành hoặc đã được xử lý/làm sạch dữ liệu. Không dùng mã giao dịch cũ đã hết hiệu lực và không tự nộp lại khoản đã bị ngân hàng trừ.\n\nLưu mã hồ sơ cũ, kỳ, thời điểm, trạng thái thanh toán và ảnh lỗi để kỹ thuật kiểm tra; chỉ thanh toán nghĩa vụ mới khi đã xác định chưa nộp."},"QA062":{"question":"Không thấy nút tiếp theo trên tờ khai cũ thì xử lý thế nào theo quy trình đảng phí mới?","answer":"Quy trình mới không bắt đảng viên phải mở tờ khai tự kê khai định kỳ và điền số tiền rồi bấm Tiếp theo.\n\nHãy vào Thu nộp Đảng phí → Xem chi tiết nghĩa vụ → chọn kỳ. Nếu số phải nộp đúng, chọn Đóng/Nộp đảng phí để thanh toán. Nếu chưa đúng, gửi Yêu cầu điều chỉnh kèm minh chứng.\n\nNếu đang xử lý hồ sơ cũ hoặc yêu cầu điều chỉnh mà nút không xuất hiện, kiểm tra các trường bắt buộc, định dạng tiền/mức đề nghị, tệp minh chứng, phân quyền và ghi nhận ảnh lỗi; không tự tạo lại nghĩa vụ."},"QA087":{"question":null,"answer":"Cần cập nhật đúng tình trạng miễn/giảm đảng phí theo hồ sơ đảng viên và quy định áp dụng. Tài khoản được phân quyền có thể kiểm tra tại Quản lý đảng viên → Cập nhật tình trạng đảng viên, phần cấu hình đảng phí.\n\nSau đó đảng viên vào Thu nộp Đảng phí → Xem chi tiết nghĩa vụ để kiểm tra hệ thống đã tính đúng tỷ lệ miễn/giảm và số phải nộp. Miễn 100% đã xác nhận đúng sẽ không phát sinh khoản phải thanh toán.\n\nNếu hệ thống chưa phản ánh tình trạng mới, gửi Yêu cầu điều chỉnh/mức đóng kèm minh chứng; không tự tạo tờ khai tháng để chờ phê duyệt."},"QA093":{"question":"Muốn xuất danh sách đảng viên chưa nộp đảng phí theo chi bộ/đảng bộ thì xem ở đâu?","answer":"Dùng Theo dõi thu nộp đảng phí → Xem chi tiết → chọn đơn vị và kỳ thu → lọc trạng thái để xem người đã nộp/chưa nộp và xuất danh sách nếu tài khoản có quyền.\n\nTừ quy trình mới, không nên đồng nhất trạng thái “chưa kê khai” với “chưa nộp”, vì nghĩa vụ được hệ thống tự tính và tự sinh theo kỳ. Với kỳ chưa mở thu hoặc chưa có dữ liệu nghĩa vụ, kiểm tra riêng tình trạng đồng bộ và miễn/giảm."},"QA094":{"question":"Trạng thái Chưa kích hoạt có đồng nghĩa chưa kê khai hoặc chưa đóng đảng phí không?","answer":"“Chưa kích hoạt” phản ánh tình trạng tài khoản/người dùng chưa kích hoạt hoặc chưa đăng nhập theo chức năng quản lý tài khoản. Không được dùng trạng thái này để kết luận đảng viên chưa kê khai hay chưa nộp đảng phí.\n\nQuy trình thu đảng phí mới tự sinh nghĩa vụ theo kỳ; muốn biết đã đóng hay chưa phải xem Theo dõi thu nộp đảng phí hoặc Xem chi tiết nghĩa vụ và trạng thái giao dịch thực tế."},"QA095":{"question":null,"answer":"Dữ liệu đảng viên và tổ chức đảng trên CSDL 4.0 là nguồn liên thông sang TTHC. Nếu danh sách TTHC thiếu, đối chiếu mã tổ chức, loại đơn vị, trạng thái đảng viên và thời điểm đồng bộ; thực hiện đồng bộ lại khi có quyền.\n\nTài khoản chưa kích hoạt hoặc chưa đăng nhập là một thông tin cần kiểm tra, nhưng không phải nguyên nhân duy nhất và không được đồng nhất với việc không có nghĩa vụ đảng phí (nghĩa vụ mới được hệ thống tự sinh theo kỳ).\n\nNếu nguồn 4.0 đã đúng nhưng TTHC vẫn thiếu người, gửi danh sách ID/mã đơn vị và ảnh trạng thái cho đầu mối hỗ trợ."},"QA101":{"question":"Nhận xét nơi cư trú cuối năm: đảng viên, chi bộ nơi công tác, chi bộ nơi cư trú và đảng ủy làm gì? Ai có quyền thao tác?","answer":"Nhận xét nơi cư trú cuối năm là QUY TRÌNH DO CHI BỘ NƠI CƯ TRÚ CHỦ ĐỘNG KHỞI TẠO, không phải đảng viên tự kê khai hoặc chi bộ nơi công tác xin nhận xét.\n\nCHUẨN BỊ THÔNG TIN NƠI CƯ TRÚ:\n- Đảng viên tự cập nhật chi bộ nơi thường trú/tạm trú lần đầu khi chưa có dữ liệu, hoặc khi chỗ ở thay đổi. Nếu đã khai đúng và không đổi thì không cập nhật lặp lại hằng năm. Khi thay đổi nơi cư trú, phải cập nhật/bổ sung trong vòng 30 ngày.\n- Bí thư chi bộ nơi công tác hoặc cán bộ được ủy quyền có thể khai báo thay: Quản lý đảng viên → Quản lý đảng viên → Cập nhật Chi bộ nơi cư trú.\n\nTRÁCH NHIỆM TỪNG BÊN:\n1. ĐẢNG VIÊN (tài khoản cá nhân): kiểm tra dữ liệu nơi cư trú; theo dõi, nhận phiếu đã xác nhận; không tự tạo hoặc ký phiếu nhận xét. Có quyền giải trình nếu nội dung chưa khách quan.\n2. CHI BỘ NƠI CÔNG TÁC/ĐANG SINH HOẠT (Bí thư hoặc cán bộ được ủy quyền): kiểm tra thông tin chi bộ cư trú; cập nhật nếu thiếu; không lập phiếu nhận xét định kỳ thay nơi cư trú; tiếp nhận phiếu đã được ký xác nhận và thông báo tại cuộc họp kiểm điểm.\n3. CHI BỘ NƠI CƯ TRÚ (chi ủy, hoặc Bí thư nếu không có chi ủy; tài khoản có quyền): họp với Ban công tác Mặt trận thôn/tổ dân phố để nhận xét trung thực. Mở Quản lý đảng viên → Quản lý đảng viên sinh hoạt nơi cư trú → tìm người → Hành động: Nhận xét → điền tiêu chí, nhận xét khác, ngày/người xử lý → Xem trước → Lưu phiếu và gửi lên cấp ủy.\n4. ĐẢNG ỦY NƠI CƯ TRÚ/CẤP TRÊN TRỰC TIẾP (tài khoản ký số có quyền): mở Chờ xử lý, tổng hợp/xác nhận, ký số, đóng dấu và phê duyệt phiếu; chuyển kết quả về chi bộ nơi công tác.\n\nHẠN THỰC HIỆN: chi bộ nơi cư trú gửi nhận xét lên cấp trên trực tiếp trước ngày 30/11 hằng năm. Quy trình điện tử được tài liệu tập huấn mô tả 3 ngày. Phiếu chỉ hoàn tất sau khi cấp ủy nơi cư trú xác nhận, ký/đóng dấu, chuyển về nơi công tác.\n\nXem toàn bộ các bước theo vai trò, nút thao tác và hai quy trình còn lại tại: https://ken1412-prog.github.io/cdstuhue-tthc/cap-nhat-tthc-2026-11.html#cuoi-nam"},"QA103":{"question":"Thông tin chi bộ nơi cư trú cập nhật một lần hay mỗi năm? Đảng viên hoặc cán bộ chi bộ cập nhật thế nào?","answer":"Thông tin chi bộ nơi cư trú phải được ghi nhận trước khi lập thủ tục nhận xét. Đây là thông tin quản lý dùng lại, KHÔNG phải hồ sơ phải khai mới mỗi cuối năm nếu thông tin vẫn đúng.\n\n- ĐẢNG VIÊN: đăng nhập, khi được yêu cầu “Cập nhật thông tin chi bộ sinh hoạt nơi cư trú” thì chọn đúng chi bộ nơi thường trú hoặc tạm trú và lưu. Khi thay đổi nơi cư trú, cập nhật trong vòng 30 ngày.\n- CHI BỘ NƠI ĐANG SINH HOẠT: Bí thư hoặc cán bộ được ủy quyền vào Quản lý đảng viên → Quản lý đảng viên, kiểm tra cột Chi bộ/Tổ chức đảng nơi cư trú; người còn trống/sai thì chọn Cập nhật Chi bộ nơi cư trú, chọn đúng tổ chức và Cập nhật.\n- CHI BỘ NƠI CƯ TRÚ: chỉ nhận được hồ sơ/đối tượng đúng khi dữ liệu định tuyến đã có và đúng. Quy trình nhận xét cuối năm do chi bộ nơi cư trú chủ động thực hiện, đảng viên không tự lập phiếu.\n\nNếu đã đúng dữ liệu nhưng không thấy đảng viên trong danh sách nơi cư trú, kiểm tra đồng bộ và quyền tài khoản được cấp; không tạo trùng hồ sơ.\n\nHướng dẫn đầy đủ: https://ken1412-prog.github.io/cdstuhue-tthc/cap-nhat-tthc-2026-11.html#cuoi-nam"},"QA112":{"question":"Chuyển sinh hoạt đảng chính thức theo giấy giới thiệu điện tử 6 ô thực hiện thế nào?","answer":"Đảng viên dùng VNeID mức 2 đăng nhập, chọn Chuyển sinh hoạt đảng chính thức, khai nơi đến, lý do/căn cứ và đính kèm bản tự kiểm điểm, quyết định liên quan rồi nộp hồ sơ.\n\n1. Chi bộ nơi đi kiểm tra hồ sơ, nhận xét bản tự kiểm điểm, PHÊ DUYỆT ĐIỆN TỬ ô 1 (không ký số ở ô này).\n2. Đảng ủy nơi đi xử lý/giới thiệu, ký số ô 2 nếu có cấp trực thuộc cơ sở tương ứng, sau đó cấp cơ sở ký số ô 3 theo luồng.\n3. Đảng ủy cơ sở nơi đến tiếp nhận và ký số ô 4; đảng ủy trực thuộc cơ sở nơi đến ký ô 5 nếu thuộc cơ cấu tương ứng.\n4. Chi bộ nơi đến ghi ngày tiếp nhận, PHÊ DUYỆT ĐIỆN TỬ ô 6, hoàn tất hồ sơ; đảng viên nhận giấy điện tử.\n\nMẫu 6 ô thay mẫu 7/10 ô; thời hạn nêu trong tài liệu đào tạo là 60 ngày làm việc kể từ khi quyết định có hiệu lực hoặc thay đổi nơi cư trú."},"QA113":{"question":"Chuyển sinh hoạt đảng tạm thời có hai chiều và 8 ô thực hiện thế nào?","answer":"Quy trình điện tử chuyển tạm thời gồm hai chiều, giấy giới thiệu 8 ô; tài liệu quy trình nêu thời hạn xử lý 30 ngày làm việc.\n\nCHIỀU ĐI (ô 1–4): đảng viên đăng nhập VNeID mức 2, chọn thủ tục, khai nơi đến, thời gian, lý do, đính kèm quyết định/căn cứ và bản tự kiểm điểm rồi gửi hồ sơ. Chi bộ chính thức kiểm tra và ký số ô 1 → đảng ủy nơi đi ký số ô 2 → đảng ủy nơi đến ký số ô 3 → chi bộ tạm thời ký số ô 4 và tiếp nhận.\n\nCHIỀU VỀ (ô 5–8): khi hoàn thành nhiệm vụ, chi bộ nơi tạm thời chủ động khởi tạo, nhận xét và ký số ô 5 → đảng ủy nơi tạm thời ký ô 6 → đảng ủy nơi chính thức ký ô 7 → chi bộ chính thức ký ô 8, tiếp nhận lại.\n\nSau mỗi chiều, hệ thống cập nhật dữ liệu sinh hoạt để quản lý đảng số và nghĩa vụ đảng phí."},"QA114":{"question":"Ba quy trình lấy ý kiến nơi cư trú khác nhau thế nào? Ai khởi tạo từng quy trình?","answer":"Có 3 QUY TRÌNH ĐỘC LẬP, không phải ba bước của một hồ sơ:\n\n1. GIỚI THIỆU VỀ NƠI CƯ TRÚ (7 ngày): chi bộ nơi đảng viên đang sinh hoạt khởi tạo khi giới thiệu mới hoặc thay đổi chỗ ở → đảng ủy nơi công tác xét/duyệt → đảng ủy nơi cư trú ký xác nhận → chi bộ cư trú tiếp nhận; đảng viên nhận giấy.\n2. LẤY Ý KIẾN PHỤC VỤ CÔNG TÁC CÁN BỘ (6 ngày): chi bộ nơi công tác lập và trình danh sách → cấp trên phê duyệt → chi bộ nơi cư trú nhận xét → đảng ủy nơi cư trú ký/đóng dấu → chi bộ nơi công tác nhận kết quả.\n3. NHẬN XÉT ĐỊNH KỲ CUỐI NĂM (3 ngày; gửi cấp trên trước 30/11): CHI BỘ NƠI CƯ TRÚ chủ động lập phiếu → đảng ủy nơi cư trú ký xác nhận → chi bộ nơi công tác nhận, thông báo khi kiểm điểm → đảng viên nhận phiếu.\n\nĐiều kiện chung: đảng viên hoặc Bí thư/cán bộ được ủy quyền ở chi bộ nơi công tác cập nhật đúng chi bộ nơi cư trú trước khi chạy thủ tục. Không phải kê khai lại mỗi năm khi không đổi, nhưng phải cập nhật trong vòng 30 ngày nếu thay đổi nơi cư trú.\n\nHướng dẫn đầy đủ từng vai trò và nút bấm: https://ken1412-prog.github.io/cdstuhue-tthc/cap-nhat-tthc-2026-11.html#cuoi-nam"},"QA115":{"question":null,"answer":"Cán bộ tiếp nhận hồ sơ TTHC xử lý theo quyền và đúng loại thủ tục:\n\n- Hồ sơ thiếu tài liệu/thông tin: chọn Yêu cầu bổ sung, ghi rõ nội dung cần bổ sung.\n- Hồ sơ không đạt điều kiện: Từ chối xử lý và nêu lý do.\n- Hồ sơ đạt: mở Chờ xử lý → Xử lý hồ sơ → Nhấn để tạo kết quả xử lý → điền biểu mẫu → Xem trước → Lưu/Ký số hoặc Phê duyệt hồ sơ theo đúng bước.\n\nKhông đồng nhất phê duyệt điện tử với ký số: chuyển sinh hoạt chính thức tại chi bộ xác nhận điện tử ô 1/6; đảng ủy ký số; chuyển tạm thời thực hiện ký số 8 ô theo thẩm quyền. Với ĐẢNG PHÍ THÔNG THƯỜNG số tiền đúng, không có bước cán bộ duyệt tờ khai."}};
window.CDSTUHUE_TTHC_CORRECTIONS=Object.freeze(corrections);
function applyModal(){
 const body=document.getElementById('modalBody'),idNode=document.getElementById('modalId');
 if(!body||!idNode||idNode.textContent.includes('MINH HỌA'))return;
 const id=String(idNode.textContent||'').trim().split(/\s+/)[0],patch=corrections[id],answer=body.querySelector('.answer');
 if(!patch||!answer)return;
 const current=String(patch.answer).trim();
 if(answer.textContent.trim()!==current)answer.textContent=current;
 answer.classList.add('tthc-current-answer');
 const heading=answer.previousElementSibling;
 if(heading?.tagName==='H3'&&heading.textContent!=='Trả lời cập nhật 05/11/2026')heading.textContent='Trả lời cập nhật 05/11/2026';
 const title=document.getElementById('modalTitle');if(title&&patch.question&&title.textContent!==patch.question)title.textContent=patch.question;
 for(const old of body.querySelectorAll('.tthc-20261105-alert,.tthc-archive-answer,.qa-click-guide'))old.remove();
 if(!body.querySelector('.tthc-source-current')){
  const source=document.createElement('div');source.className='tthc-source-current';
  const link=document.createElement('a');link.textContent='Xem hướng dẫn thao tác 04 TTHC';link.href=['QA101','QA103','QA114'].includes(id)?'cap-nhat-tthc-2026-11.html#cuoi-nam':'cap-nhat-tthc-2026-11.html';link.rel='noopener noreferrer';link.target='_blank';source.append(link);answer.after(source);
 }
}
function applyCards(){
 const page=document.getElementById('page');if(!page)return;
 for(const card of page.querySelectorAll('.qa-item[data-qa]')){
  const patch=corrections[card.dataset.qa];if(!patch)continue;
  const h=card.querySelector('h3');if(h&&patch.question&&h.textContent!==patch.question)h.textContent=patch.question;
  const p=card.querySelector('p');const brief=String(patch.answer).split(/\n\s*\n/)[0];
  if(p&&p.textContent!==brief)p.textContent=brief;
 }
}
function boot(){const body=document.getElementById('modalBody'),page=document.getElementById('page');
 if(body)new MutationObserver(applyModal).observe(body,{childList:true});
 if(page)new MutationObserver(applyCards).observe(page,{childList:true});
 applyModal();applyCards();
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();